<?php

declare(strict_types=1);

use App\Board\IdeBoardStub;
use PhpBaremetal\Spec\Sdk\Descriptor\Board;
use Tests\Support\Fixtures;

function pinsBoard(array $pins): Board
{
    return Board::fromArray('nano', ['name' => 'Nano', 'chip' => 'esp32s3', 'flash' => '16MB', 'pins' => $pins], 'nano.json');
}

it('declares the pins as constants of Baremetal\Board\Pin, in the file order', function () {
    $php = IdeBoardStub::render(pinsBoard(['D13' => 48, 'A3' => 4, 'LED_BUILTIN' => 48]), false);

    expect($php)->toBe(<<<'PHP'
        <?php

        // Generated by phpbm, do not edit: the pin names of board nano, for the IDE.
        // phpbm rewrites this file at init, board and build.

        namespace Baremetal\Board {
            final class Pin
            {
                public const D13 = 48;
                public const A3 = 4;
                public const LED_BUILTIN = 48;
            }
        }

        PHP);
});

it('declares global constants too with board-constants global', function () {
    $php = IdeBoardStub::render(pinsBoard(['D13' => 48, 'A3' => 4]), true);

    expect($php)->toEndWith("}\n\nnamespace {\n    const D13 = 48;\n    const A3 = 4;\n}\n");
});

it('declares an empty class when the board has no pins', function () {
    $php = IdeBoardStub::render(pinsBoard([]), true);

    expect($php)->toContain("    final class Pin\n    {\n    }\n")
        ->and($php)->toEndWith("namespace {\n}\n");
});

it('renders valid php', function () {
    $dir = Fixtures::tempDir();
    IdeBoardStub::write($dir, pinsBoard(['D13' => 48]), true);

    $output = [];
    exec(escapeshellarg(PHP_BINARY) . ' -l ' . escapeshellarg($dir . '/' . IdeBoardStub::PATH), $output, $exit);
    expect($exit)->toBe(0);
});

it('writes the file under .phpbm/ide and rewrites it only when it changes', function () {
    $dir = Fixtures::tempDir();
    $path = $dir . '/.phpbm/ide/board.php';

    expect(IdeBoardStub::write($dir, pinsBoard(['D13' => 48]), false))->toBeTrue()
        ->and(file_get_contents($path))->toContain('public const D13 = 48;')
        ->and(IdeBoardStub::write($dir, pinsBoard(['D13' => 48]), false))->toBeFalse()
        ->and(IdeBoardStub::write($dir, pinsBoard(['D13' => 48]), true))->toBeTrue()
        ->and(file_get_contents($path))->toContain('const D13 = 48;');
});

it('reads board-constants from the project options, class when absent', function () {
    expect(IdeBoardStub::global(['board-constants' => 'global']))->toBeTrue()
        ->and(IdeBoardStub::global(['board-constants' => 'class']))->toBeFalse()
        ->and(IdeBoardStub::global(['board-constants' => ['global']]))->toBeTrue()
        ->and(IdeBoardStub::global([]))->toBeFalse()
        ->and(IdeBoardStub::global(['on-error' => 'stop']))->toBeFalse();
});
